var n=`1424-nauruan-coconut-crusted-fish`;var a=`world-1424`;var t=`NR`;var r=`oceania`;var u=4;var c=34;var s={en:`Nauruan Coconut-Crusted Fish`,ua:`Риба в кокосовій паніровці по-науруанськи`};var o={en:`Nauru-inspired pan-fried fish in a crisp desiccated-coconut coating.`,ua:`Риба в хрусткій кокосовій паніровці, смажена на сковороді за мотивами кухні Науру.`};var l=[{en:`Cut fish into four equal fillets, dry well and season with salt and pepper.`,ua:`Розділіть рибу на чотири однакові шматки, обсушіть і приправте сіллю та перцем.`,t:[`seasoning`],m:6,i:[[`mahi-mahi`,650,`g`],[`sea-salt`,5,`g`],[`ground-black-pepper`,2,`g`]]},{en:`Prepare three bowls: flour, beaten egg, and desiccated coconut mixed with cracker crumbs.`,ua:`Підготуйте три миски: з борошном, збитим яйцем та кокосовою стружкою, змішаною з крихтою крекерів.`,t:[`mise-en-place`],m:5,i:[[`all-purpose-flour`,65,`g`],[`chicken-egg`,2,`pcs`],[`desiccated-coconut`,110,`g`],[`cracker-crumbs`,45,`g`]]},{en:`Coat each fillet with flour, then egg, then coconut mixture; press lightly to adhere.`,ua:`Обкачайте кожне філе в борошні, потім у яйці та кокосовій суміші; злегка притисніть паніровку.`,t:[`crusting`],m:8,i:[]},{en:`Pan-fry in oil over medium heat 4–6 minutes per side until golden and the fish reaches 63°C internally; lower heat if coconut browns too quickly.`,ua:`Смажте на сковороді на помірному вогні по 4–6 хвилин з кожного боку до золотистого кольору й температури 63°C усередині риби; зменште вогонь, якщо кокос надто швидко темнішає.`,t:[`pan-frying`],m:12,i:[[`vegetable-oil-neutral`,85,`ml`]]},{en:`Drain briefly and serve with lime juice.`,ua:`Дайте зайвій олії стекти й подавайте з соком лайма.`,t:[`draining`],m:3,i:[[`lime-juice`,40,`ml`]]}];var d={slug:n,id:a,country:`NR`,region:r,servings:4,minutes:34,title:s,text:o,steps:l};export{t as country,d as default,a as id,c as minutes,r as region,u as servings,n as slug,l as steps,o as text,s as title};